local BellPullMaker = {}
local PRODUCTS = {
    hempen_pull = { name = "Konopljev zvonec-povod", hempCost = 1, time = 1, cost = 4, length = 5, description = "Preprost konopljev povod za zvonce." },
    braided_pull = { name = "Pleteni zvonec-povod", hempCost = 2, time = 2, cost = 14, length = 10, prestige = 1, description = "Pleteni povod z okrasnimi vozlji." },
    silk_pull = { name = "Svileni zvonec-povod", silkCost = 1, hempCost = 1, time = 3, cost = 38, length = 15, prestige = 3, description = "Svileni povod za plemiške dvorane." },
    tasseled_pull = { name = "Kitasti zvonec-povod", silkCost = 2, time = 4, cost = 80, length = 18, prestige = 5, description = "Povod z zlatimi obstoječimi kite." },
    silver_wire_pull = { name = "Srebrnožični povod", silverCost = 2, silkCost = 1, time = 5, cost = 165, length = 22, prestige = 9, happiness = 1, description = "Povod z integrirano srebrno žico za vzdržljivost." },
    royal_ceremonial_pull = { name = "Kraljevski slovesni povod", goldCost = 2, silverCost = 2, silkCost = 3, time = 8, cost = 420, length = 30, prestige = 22, happiness = 4, description = "Slovesni povod z zlatimi in srebrnimi okraski za kraljevsko kapelo." },
}
local BUILDINGS = {
    workshop = { name = "Povodarska delavnica", cost = { gold = 180, wood = 100 }, upkeep = 4, qualityBonus = 5 },
    braiding_room = { name = "Pletilnica", cost = { gold = 600, wood = 200, stone = 150 }, upkeep = 15, qualityBonus = 15 },
    silk_room = { name = "Svilničnica", cost = { gold = 1100, wood = 250, stone = 250, silver = 20 }, upkeep = 25, qualityBonus = 22 },
    royal_pull_atelier = { name = "Kraljevski atelje povodov", cost = { gold = 3000, wood = 400, stone = 500, gold = 30 }, upkeep = 60, qualityBonus = 36, prestigeBonus = 17 },
}
BellPullMaker.hempStock = 22; BellPullMaker.silkStock = 8; BellPullMaker.silverStock = 5; BellPullMaker.goldStock = 3
BellPullMaker.productStock = {}; BellPullMaker.buildings = {}; BellPullMaker.maker = nil; BellPullMaker.activeMaking = {}; BellPullMaker.totalProducts = 0; BellPullMaker.dayTimer = 0
function BellPullMaker.init() BellPullMaker.hempStock=22; BellPullMaker.silkStock=8; BellPullMaker.silverStock=5; BellPullMaker.goldStock=3; BellPullMaker.productStock={}; BellPullMaker.buildings={}; BellPullMaker.maker=nil; BellPullMaker.activeMaking={}; BellPullMaker.totalProducts=0; BellPullMaker.dayTimer=0; print("[BellPullMaker] Royal Bell Pull System initialized (6 products, 4 buildings)") end
function BellPullMaker.hireMaker(n,s) s=s or math.random(35,80); local c=240+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BellPullMaker.maker={name=n or ("Povodar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Povodar najet: %s (spretnost: %d)",BellPullMaker.maker.name,s),"success") end; return true end
function BellPullMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BellPullMaker.build(id) local ok,e=BellPullMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BellPullMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BellPullMaker.getQualityBonus() local b=0; for _,bd in ipairs(BellPullMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BellPullMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.hempCost and BellPullMaker.hempStock<(d.hempCost or 0) then return false,"Premalo konoplje" end; if d.silkCost and BellPullMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.silverCost and BellPullMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BellPullMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #BellPullMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BellPullMaker.maker then return false,"Potreben povodar" end; return true end
function BellPullMaker.make(pt,qty) qty=qty or 5; local ok,e=BellPullMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.hempCost then BellPullMaker.hempStock=BellPullMaker.hempStock-d.hempCost*qty end; if d.silkCost then BellPullMaker.silkStock=BellPullMaker.silkStock-d.silkCost*qty end; if d.silverCost then BellPullMaker.silverStock=BellPullMaker.silverStock-d.silverCost*qty end; if d.goldCost then BellPullMaker.goldStock=BellPullMaker.goldStock-d.goldCost*qty end; local t=d.time; if BellPullMaker.maker then t=math.max(1,t-math.floor(BellPullMaker.maker.skill/15)) end; table.insert(BellPullMaker.activeMaking,{id="pull_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,length=d.length or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BellPullMaker.completeMaking(m) local q=1.0+(BellPullMaker.getQualityBonus()/100); if BellPullMaker.maker then q=q+(BellPullMaker.maker.skill/200) end; q=math.min(2.0,q); BellPullMaker.productStock[m.productType]=(BellPullMaker.productStock[m.productType] or 0)+m.quantity; BellPullMaker.totalProducts=BellPullMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BellPullMaker.maker then BellPullMaker.maker.itemsMade=BellPullMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then BellPullMaker.maker.skill=math.min(100,BellPullMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Povodi izdelani: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function BellPullMaker.update(dt) if not _G.state then return end; BellPullMaker.dayTimer=BellPullMaker.dayTimer+dt; if BellPullMaker.dayTimer>=30 then BellPullMaker.dayTimer=0; for i=#BellPullMaker.activeMaking,1,-1 do local m=BellPullMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BellPullMaker.completeMaking(m); table.remove(BellPullMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BellPullMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BellPullMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BellPullMaker.getStats() return {hempStock=BellPullMaker.hempStock,silkStock=BellPullMaker.silkStock,silverStock=BellPullMaker.silverStock,goldStock=BellPullMaker.goldStock,productStock=BellPullMaker.productStock,numBuildings=#BellPullMaker.buildings,hasMaker=BellPullMaker.maker~=nil,makerName=BellPullMaker.maker and BellPullMaker.maker.name or "—",makerSkill=BellPullMaker.maker and BellPullMaker.maker.skill or 0,activeMaking=#BellPullMaker.activeMaking,totalProducts=BellPullMaker.totalProducts} end
return BellPullMaker
